#nullable enable

using JasperFx.Events.Daemon;        // DaemonMode — no doc page states this namespace; verified by compiling
using JasperFx.Events.Projections;
using Marten;
using Spend.Views;

namespace Spend;

/// <summary>
/// Called once from Program.cs. Every line below is the DEFAULT, not the answer: single- or
/// multi-stream, registered Inline. Marten also offers EventProjection (one event, many documents),
/// FlatTableProjection (a SQL table, not a document), composite/chained projections and raw
/// IProjection — see reference/llms/marten/events/projections/ and
/// reference-implementations/state-view/.
///
/// Changing a line here is the supported way to choose. Regeneration KEEPS this file.
///
/// Two costs to know before moving anything off Inline:
///   - Inline updates the view in the append's own transaction, so a GWT's THEN is assertable the
///     moment the request returns. Async means tests must WAIT instead of assert.
///   - Async needs the daemon: AddAsyncDaemon(DaemonMode.Solo) on the Marten chain, or nothing runs
///     and Marten only warns.
/// </summary>
public static class ViewRegistrations
{
    public static void Register(StoreOptions opts)
    {
        // INLINE, DELIBERATELY, AND AGAINST MARTEN'S GENERAL GUIDANCE FOR MULTI-STREAM VIEWS.
        //
        // This folder exists to answer one question: can a multi-stream aggregation guard a
        // cross-aggregate invariant? Inline is the STRONGEST form of that claim — the view is updated
        // inside the append's own transaction, so a reader sees no lag at all. Async is strictly weaker:
        // the daemon trails the append, so a check against it is stale by construction and the race is
        // trivial. Testing the weak form first would prove nothing about the strong one.
        //
        // So: if the race beats Inline, it beats Async a fortiori — and that is the finding, not a
        // recommendation to register multi-stream views Inline generally.
        opts.Projections.Add<DepartmentSpendProjection>(ProjectionLifecycle.Inline);

        // ARM 1's guard row, and the registration IS REQUIRED — measured, against the docs' wording.
        // documents/concurrency.md says that for an IRevisioned document "Store() is essentially
        // UpdateRevision(entity, entity.Version)", which reads as automatic. It is not: with the
        // interface alone and no registration, two racing writers both committed and the invariant broke
        // exactly as in the naive arm. UseNumericRevisions(true) is what turns the version column into a
        // enforced predicate.
        opts.Schema.For<Spend.Concurrency.DepartmentBudgetGuard>().UseNumericRevisions(true);

        // ARM 2's reservation row. THE UNIQUE INDEX IS THE ENTIRE MECHANISM — without it the two racing
        // inserts are simply two rows and nothing collides, so this arm degrades silently into the naive
        // one. Computed (the default index type per documents/indexing/unique.md) rather than duplicated
        // fields: no extra columns, and neither field is ever queried on its own.
        opts.Schema.For<Spend.Concurrency.BudgetReservation>()
            .UniqueIndex(x => x.DepartmentId, x => x.Sequence);

        // ARM 4's tag type. Each registered tag gets its own table (mt_event_tag_department) plus a row
        // in mt_dcb_tag_version — the side table added in Marten 9.4 that IS the serialization point, and
        // the reason this folder is pinned off the kit's Marten 8.
        opts.Events.RegisterTagType<Spend.Concurrency.DepartmentTag>("department")
            .ForAggregate<Spend.Concurrency.DepartmentBoundary>();
    }

    /// <summary>
    /// The read side sometimes needs the STORE and not just its options. Any projection registered Async
    /// runs in the async daemon, and WITHOUT THE DAEMON NOTHING PROCESSES IT — Marten only logs a warning
    /// at startup, so the symptom is a view that stays empty for ever with a clean build and a clean boot.
    ///
    /// Solo rather than HotCold: one node, no leader election, much faster startup.
    /// </summary>
    public static void ConfigureStore(MartenServiceCollectionExtensions.MartenConfigurationExpression marten)
    {
        // NOTHING HERE IS REGISTERED ASYNC — DepartmentSpend is deliberately Inline, for the reason given
        // at its registration above. This comment previously claimed the opposite, which mattered more than
        // a stale comment usually does: Inline is the STRONGEST form of the claim this folder tests, and a
        // reader who believed the view was Async would conclude the race only beats a lagging projection.
        //
        // The daemon is started anyway because it costs nothing here and a projection moved off Inline
        // during an experiment would otherwise silently never update — Marten only logs a warning.
        marten.AddAsyncDaemon(DaemonMode.Solo);
    }
}
